118	func (r *Runner) run(ctx context.Context, binary string, req harnesses.ExecuteRequest, out chan<- harnesses.Event) {
119		defer close(out)
120	
121		start := time.Now()
122		var seq int64
123	
124		agg, exitCode, stderr, runErr, status := r.runStreaming(ctx, binary, req, out, &seq)
125	
126		final := harnesses.FinalData{
127			Status:     status,
128			ExitCode:   exitCode,
129			DurationMS: time.Since(start).Milliseconds(),
130		}
131		if runErr != nil && status != "success" {
132			final.Error = runErr.Error()
133		} else if stderr != "" && status != "success" {
134			final.Error = trimErrorBlob(stderr)
135		}
136		if agg != nil {
137			final.FinalText = agg.FinalText
138			final.Usage, final.Warnings = harnesses.ResolveFinalUsage(agg.UsageSources)
139			final.CostUSD = agg.CostUSD
140		}
141	
142		finalRaw, err := json.Marshal(final)
143		if err != nil {
144			finalRaw = []byte(`{"status":"failed","error":"marshal final event"}`)
145		}
146		ev := harnesses.Event{
147			Type:     harnesses.EventTypeFinal,
148			Sequence: seq,
149			Time:     time.Now().UTC(),
150			Metadata: req.Metadata,
151			Data:     finalRaw,
152		}
153		select {
154		case out <- ev:
155		case <-time.After(time.Second):
156		}
157	}
