159	func (r *Runner) runStreaming(ctx context.Context, binary string, req harnesses.ExecuteRequest, out chan<- harnesses.Event, seq *int64) (agg *streamAggregate, exitCode int, stderr string, runErr error, status string) {
160		base := r.BaseArgs
161		if base == nil {
162			base = []string{"run", "--format", "json"}
163		}
164		args := append([]string{}, base...)
165	
166		// opencode run auto-approves all tool permissions; no extra flags per level.
167	
168		// WorkDir flag: --dir <dir>
169		if req.WorkDir != "" {
170			args = append(args, "--dir", req.WorkDir)
171		}
172	
173		// Model flag: -m <model>
174		if req.Model != "" {
175			args = append(args, "-m", opencodeModelArg(req.Provider, req.Model))
176		}
177	
178		// Reasoning flag: --variant <reasoning>
179		if value := harnesses.AdapterReasoningValue(req); value != "" {
180			args = append(args, "--variant", value)
181		}
182	
183		promptMode := r.PromptMode
184		if promptMode == "" {
185			promptMode = "arg"
186		}
187		if promptMode == "arg" && req.Prompt != "" {
188			args = append(args, req.Prompt)
189		}
190	
191		runCtx, cancel := context.WithCancel(ctx)
192		defer cancel()
193	
194		cmd := harnesses.HarnessCommand(runCtx, binary, args...)
195		if req.WorkDir != "" {
196			cmd.Dir = req.WorkDir
197		}
198		if promptMode != "arg" {
199			cmd.Stdin = strings.NewReader(req.Prompt)
200		}
201		setProcessGroup(cmd)
202	
203		stdoutPipe, err := cmd.StdoutPipe()
204		if err != nil {
205			return nil, -1, "", err, "failed"
206		}
207		stderrPipe, err := cmd.StderrPipe()
208		if err != nil {
209			return nil, -1, "", err, "failed"
210		}
211	
212		if err := cmd.Start(); err != nil {
213			return nil, -1, "", err, "failed"
214		}
215		defer killProcessGroup(cmd)
216		_ = harnesses.RegisterHarnessSession(req.SessionLogDir, req.SessionID, "opencode", cmd)
217	
218		progressLog, _ := harnesses.OpenProgressLog(req.SessionLogDir, req.SessionID, "opencode")
219		if progressLog != nil {
220			defer progressLog.Close()
221		}
222	
223		parserReader, parserWriter := io.Pipe()
224		parseDone := make(chan struct{})
225		var parseAgg *streamAggregate
226		var parseErr error
227		go func() {
228			defer close(parseDone)
229			mirrored, mirrorDone := harnesses.MirrorEvents(out, progressLog, ctx)
230			parseAgg, parseErr = parseOpencodeStream(runCtx, parserReader, mirrored, req.Metadata, seq)
231			close(mirrored)
232			<-mirrorDone
233		}()
234	
235		stdoutDone := make(chan struct{})
236		go func() {
237			defer close(stdoutDone)
238			_, _ = io.Copy(parserWriter, stdoutPipe)
239			_ = parserWriter.Close()
240		}()
241	
242		var stderrBuf strings.Builder
243		stderrDone := make(chan struct{})
244		go func() {
245			defer close(stderrDone)
246			_, _ = io.Copy(&stringBuilderWriter{&stderrBuf}, stderrPipe)
247		}()
248	
249		var timedOut atomic.Bool
250		if req.Timeout > 0 {
251			stop := make(chan struct{})
252			go func() {
253				select {
254				case <-stop:
255				case <-time.After(req.Timeout):
256					timedOut.Store(true)
257					cancel()
258					killProcessGroup(cmd)
259				}
260			}()
261			defer close(stop)
262		}
263	
264		// Wait for stdout to be fully read; context cancellation also wakes us up.
265		// Either way, the defer ensures process group is killed on function exit.
266		select {
267		case <-runCtx.Done():
268		case <-stdoutDone:
269		}
270	
271		<-stderrDone
272		<-parseDone
273		runErr = cmd.Wait()
274		stderr = stderrBuf.String()
275	
276		switch {
277		case timedOut.Load():
278			return parseAgg, -1, stderr, context.DeadlineExceeded, "timed_out"
279		case ctx.Err() != nil && errors.Is(ctx.Err(), context.Canceled):
280			return parseAgg, -1, stderr, ctx.Err(), "cancelled"
281		case ctx.Err() != nil && errors.Is(ctx.Err(), context.DeadlineExceeded):
282			return parseAgg, -1, stderr, ctx.Err(), "timed_out"
283		case runErr != nil:
284			ec := -1
285			var exitErr *osexec.ExitError
286			if errors.As(runErr, &exitErr) {
287				ec = exitErr.ExitCode()
288			}
289			return parseAgg, ec, stderr, runErr, "failed"
290		}
291		if parseErr != nil && !errors.Is(parseErr, context.Canceled) {
292			return parseAgg, 0, stderr, parseErr, "failed"
293		}
294		return parseAgg, 0, stderr, nil, "success"
295	}
