297	func opencodeModelArg(provider, model string) string {
298		provider = strings.TrimSpace(provider)
299		model = strings.TrimSpace(model)
300		if provider == "" || model == "" || strings.Contains(model, "/") {
301			return model
302		}
303		return provider + "/" + model
304	}
