306	type stringBuilderWriter struct {
307		sb *strings.Builder
308	}
309	
310	func (w *stringBuilderWriter) Write(p []byte) (int, error) {
311		return w.sb.Write(p)
312	}
313	
314	func trimErrorBlob(s string) string {
315		const max = 2048
316		s = strings.TrimSpace(s)
317		if len(s) > max {
318			return s[:max] + "...(truncated)"
319		}
320		return s
321	}
322	
323	func setProcessGroup(cmd *osexec.Cmd) {
324		if cmd.SysProcAttr == nil {
325			cmd.SysProcAttr = &syscall.SysProcAttr{}
326		}
327		setProcessGroupAttr(cmd.SysProcAttr)
328	}
