330	// DefaultModelSnapshot implements harnesses.ModelDiscoveryHarness. It calls
331	// the live opencode models discovery helper with a sensible timeout; on failure,
332	// returns ErrModelDiscoveryEvidenceMissing per the no-static-fallback principle.
333	func (r *Runner) DefaultModelSnapshot() (harnesses.ModelDiscoverySnapshot, error) {
334		binary := r.Binary
335		if binary == "" {
336			binary = "opencode"
337		}
338		snapshot, err := readOpenCodeModelDiscovery(context.Background(), binary)
339		if err != nil {
340			return harnesses.ModelDiscoverySnapshot{}, fmt.Errorf("model discovery: %w", err)
341		}
342		if len(snapshot.Models) == 0 {
343			return harnesses.ModelDiscoverySnapshot{}, harnesses.ErrModelDiscoveryEvidenceMissing
344		}
345		return snapshot, nil
346	}
