348	// SupportedAliases returns nil: opencode requires exact provider/model
349	// identifiers and recognizes no family alias. Implements
350	// harnesses.ModelDiscoveryHarness.
351	func (r *Runner) SupportedAliases() []string {
352		return nil
353	}
354	
355	// ResolveModelAlias always returns harnesses.ErrAliasNotResolvable because
356	// opencode does not recognize family aliases. Implements
357	// harnesses.ModelDiscoveryHarness.
358	func (r *Runner) ResolveModelAlias(family string, snapshot harnesses.ModelDiscoverySnapshot) (string, error) {
359		return "", harnesses.ErrAliasNotResolvable
360	}
