116	func resolveRunnerModel(cache *ModelDiscoveryCache, harnessName string, surface modelcatalog.Surface, requestedModel, fallbackDefault string) RunnerModelResolution {
117		resolution := RunnerModelResolution{
118			HarnessName:       harnessName,
119			RequestedModel:    requestedModel,
120			PriorDefaultModel: fallbackDefault,
121			Surface:           string(surface),
122			Source:            EmbeddedDiscoverySource,
123		}
124	
125		requestedModel = strings.TrimSpace(requestedModel)
126		if requestedModel != "" {
127			resolution.ResolvedModel = requestedModel
128			resolution.ExplicitPin = true
129			snapshot, err := cache.Snapshot(harnessName, EmbeddedDiscoverySource)
130			if err != nil {
131				resolution.Warning = fmt.Sprintf("model discovery unavailable for explicit pin validation: %v", err)
132				resolution.Reason = "explicit_pin_discovery_unavailable"
133				return resolution
134			}
135			resolution.Source = snapshot.Source
136			if !stringInSliceFold(requestedModel, snapshot.Models) {
137				resolution.Warning = fmt.Sprintf("explicit model pin %q was not present in %s snapshot", requestedModel, snapshot.Source)
138				resolution.Reason = "explicit_pin_absent_from_snapshot"
139			}
140			return resolution
141		}
142	
143		snapshot, err := cache.Snapshot(harnessName, EmbeddedDiscoverySource)
144		if err != nil {
145			resolution.ResolvedModel = fallbackDefault
146			resolution.Warning = fmt.Sprintf("model discovery lookup failed; using fallback default %q: %v", fallbackDefault, err)
147			resolution.Reason = "discovery_lookup_failed"
148			return resolution
149		}
150		resolution.Source = snapshot.Source
151	
152		catalog, err := modelcatalog.Default()
153		if err != nil {
154			resolution.ResolvedModel = fallbackDefault
155			resolution.Warning = fmt.Sprintf("model catalog load failed; using fallback default %q: %v", fallbackDefault, err)
156			resolution.Reason = "catalog_load_failed"
157			return resolution
158		}
159	
160		candidates := autoRoutableSnapshotCandidates(catalog, snapshot, surface)
161		if len(candidates) == 0 {
162			resolution.ResolvedModel = fallbackDefault
163			resolution.Warning = fmt.Sprintf("model discovery snapshot %s had no auto-routable catalog candidates; using fallback default %q", snapshot.Source, fallbackDefault)
164			resolution.Reason = "no_auto_routable_discovery_candidate"
165			return resolution
166		}
167		sort.SliceStable(candidates, func(i, j int) bool {
168			if cmp := candidates[i].parsed.Compare(candidates[j].parsed); cmp != 0 {
169				return cmp < 0
170			}
171			if candidates[i].power != candidates[j].power {
172				return candidates[i].power > candidates[j].power
173			}
174			return candidates[i].order < candidates[j].order
175		})
176	
177		resolution.ResolvedModel = candidates[0].model
178		if resolution.ResolvedModel != fallbackDefault {
179			resolution.Reason = "discovery_default_changed"
180		}
181		return resolution
182	}
183	
184	func autoRoutableSnapshotCandidates(catalog *modelcatalog.Catalog, snapshot ModelDiscoverySnapshot, surface modelcatalog.Surface) []modelCandidate {
185		seen := make(map[string]bool)
186		candidates := make([]modelCandidate, 0, len(snapshot.Models))
187		for i, modelID := range snapshot.Models {
188			modelID = strings.TrimSpace(modelID)
189			if modelID == "" {
190				continue
191			}
192			eligibility, ok := catalog.ModelEligibility(modelID)
193			if !ok || !eligibility.AutoRoutable {
194				continue
195			}
196			resolved, err := catalog.Resolve(modelID, modelcatalog.ResolveOptions{Surface: surface})
197			if err != nil || resolved.ConcreteModel == "" {
198				continue
199			}
200			if seen[resolved.ConcreteModel] {
201				continue
202			}
203			seen[resolved.ConcreteModel] = true
204			candidates = append(candidates, modelCandidate{
205				model:  resolved.ConcreteModel,
206				parsed: modelcatalog.Parse(resolved.ConcreteModel),
207				power:  eligibility.Power,
208				order:  i,
209			})
210		}
211		return candidates
212	}
