267				return nil, -1, "", ctx.Err(), "cancelled"
268			}
269		}
270		if harnesses.ShouldEmitRunnerReasoningResolution(reasoningResolution) {
271			harnesses.LogRunnerReasoningWarning(reasoningResolution)
272			ev := harnesses.RunnerReasoningResolutionEvent(reasoningResolution, req.Metadata, seq)
273			harnesses.WriteProgressEvent(progressLog, ev)
274			select {
275			case out <- ev:
276			case <-ctx.Done():
277				return nil, -1, "", ctx.Err(), "cancelled"
278			}
279		}
280	
281		parserReader, parserWriter := io.Pipe()
282		parseDone := make(chan struct{})
283		var parseAgg *streamAggregate
284		var parseErr error
285		go func() {
