241	func TestRunner_Execute_HappyPath(t *testing.T) {
242		if _, err := exec.LookPath("sh"); err != nil {
243			t.Skip("sh not available")
244		}
245	
246		// Write a fake "codex" script.
247		script := `#!/bin/sh
248	cat <<'EOF'
249	{"type":"output","item":{"type":"agent_message","text":"hello from codex"}}
250	{"type":"turn.completed","usage":{"input_tokens":10,"output_tokens":5}}
251	EOF
252	`
253		f, err := os.CreateTemp("", "fake-codex-*")
254		if err != nil {
255			t.Fatal(err)
256		}
257		defer os.Remove(f.Name())
258		if _, err := f.WriteString(script); err != nil {
259			t.Fatal(err)
260		}
261		f.Close()
262		if err := os.Chmod(f.Name(), 0o755); err != nil {
263			t.Fatal(err)
264		}
265	
266		r := &Runner{
267			Binary:   f.Name(),
268			BaseArgs: []string{}, // skip "exec --json" so the script runs cleanly
269		}
270	
271		ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
272		defer cancel()
273	
274		ch, err := r.Execute(ctx, harnesses.ExecuteRequest{
275			Prompt: "test prompt",
276		})
277		if err != nil {
278			t.Fatalf("Execute: %v", err)
279		}
280	
281		var textDeltas []string
282		var finalEv *harnesses.FinalData
283		for ev := range ch {
284			switch ev.Type {
285			case harnesses.EventTypeTextDelta:
286				var d harnesses.TextDeltaData
287				if err := json.Unmarshal(ev.Data, &d); err != nil {
288					t.Errorf("unmarshal text_delta: %v", err)
289				}
290				textDeltas = append(textDeltas, d.Text)
291			case harnesses.EventTypeFinal:
292				var fd harnesses.FinalData
293				if err := json.Unmarshal(ev.Data, &fd); err != nil {
294					t.Errorf("unmarshal final: %v", err)
295				}
296				finalEv = &fd
297			}
298		}
299	
300		if len(textDeltas) == 0 {
301			t.Error("expected at least one text_delta event")
302		} else if !strings.Contains(textDeltas[0], "hello from codex") {
303			t.Errorf("unexpected text delta: %q", textDeltas[0])
304		}
305	
306		if finalEv == nil {
307			t.Fatal("no final event received")
308		}
309		if finalEv.Status != "success" {
310			t.Errorf("expected status=success, got %q (error: %s)", finalEv.Status, finalEv.Error)
311		}
312		if finalEv.FinalText != "hello from codex" {
313			t.Errorf("expected FinalText=%q, got %q", "hello from codex", finalEv.FinalText)
314		}
315		if finalEv.Usage == nil {
316			t.Error("expected usage in final event")
317		} else {
318			if finalEv.Usage.InputTokens == nil || *finalEv.Usage.InputTokens != 10 {
319				t.Errorf("expected InputTokens=10, got %#v", finalEv.Usage.InputTokens)
320			}
321			if finalEv.Usage.OutputTokens == nil || *finalEv.Usage.OutputTokens != 5 {
322				t.Errorf("expected OutputTokens=5, got %#v", finalEv.Usage.OutputTokens)
323			}
324			if finalEv.Usage.TotalTokens == nil || *finalEv.Usage.TotalTokens != 15 {
325				t.Errorf("expected TotalTokens=15, got %#v", finalEv.Usage.TotalTokens)
326			}
327		}
328	}
