502		out := make(chan harnesses.Event, 16)
503		var seq int64
504		if _, err := parseCodexStream(context.Background(), strings.NewReader(input), out, nil, &seq); err != nil {
505			t.Fatalf("parseCodexStream: %v", err)
506		}
507		close(out)
508		var events []harnesses.Event
509		for ev := range out {
510			events = append(events, ev)
511		}
512		if len(events) != 2 {
513			t.Fatalf("events: got %d, want 2", len(events))
514		}
515		var result harnesses.ToolResultData
516		if err := json.Unmarshal(events[1].Data, &result); err != nil {
517			t.Fatalf("unmarshal tool_result: %v", err)
