570	func TestParseCodexStream_UsageCassettes(t *testing.T) {
571		cases := []struct {
572			name             string
573			wantUsage        bool
574			wantInput        int
575			wantOutput       int
576			wantCache        int
577			wantReasoning    int
578			wantSource       string
579			wantRateLimits   int
580			wantMalformed    bool
581			wantDisagreement bool
582		}{
583			{name: "present", wantUsage: true, wantInput: 12, wantOutput: 4, wantCache: 5, wantReasoning: 2, wantSource: harnesses.UsageSourceNativeStream},
584			{name: "absent"},
585			{name: "malformed", wantMalformed: true},
586			{name: "disagree", wantUsage: true, wantInput: 30, wantOutput: 6, wantSource: harnesses.UsageSourceNativeStream, wantDisagreement: true},
587			{name: "token_count_only", wantUsage: true, wantInput: 11, wantOutput: 3, wantCache: 8, wantReasoning: 1, wantSource: harnesses.UsageSourceNativeTokenCount, wantRateLimits: 1},
588			{name: "token_count_with_turn", wantUsage: true, wantInput: 20, wantOutput: 4, wantSource: harnesses.UsageSourceNativeStream, wantRateLimits: 1, wantDisagreement: true},
589			{name: "token_count_malformed", wantMalformed: true},
590		}
591		for _, tc := range cases {
592			t.Run(tc.name, func(t *testing.T) {
593				data, err := os.ReadFile(filepath.Join("testdata", "usage_cassettes", tc.name+".jsonl"))
594				if err != nil {
595					t.Fatalf("read cassette: %v", err)
596				}
597				out := make(chan harnesses.Event, 16)
598				var seq int64
599				agg, err := parseCodexStream(context.Background(), strings.NewReader(string(data)), out, nil, &seq)
600				close(out)
601				if err != nil {
602					t.Fatalf("parseCodexStream: %v", err)
603				}
604				usage, warnings := harnesses.ResolveFinalUsage(agg.UsageSources)
605				if !tc.wantUsage {
606					if usage != nil {
607						t.Fatalf("usage: got %#v, want nil", usage)
608					}
609				} else {
610					if usage == nil || usage.InputTokens == nil || *usage.InputTokens != tc.wantInput {
611						t.Fatalf("input usage: got %#v", usage)
612					}
613					if usage.OutputTokens == nil || *usage.OutputTokens != tc.wantOutput {
614						t.Fatalf("output usage: got %#v", usage)
615					}
616					if tc.wantSource != "" && usage.Source != tc.wantSource {
617						t.Fatalf("usage source: got %q, want %q", usage.Source, tc.wantSource)
618					}
619					if tc.wantCache > 0 && (usage.CacheTokens == nil || *usage.CacheTokens != tc.wantCache) {
620						t.Fatalf("cache usage: got %#v", usage)
621					}
622					if tc.wantReasoning > 0 && (usage.ReasoningTokens == nil || *usage.ReasoningTokens != tc.wantReasoning) {
623						t.Fatalf("reasoning usage: got %#v", usage)
624					}
625				}
626				if len(agg.TokenCountRateLimits) != tc.wantRateLimits {
627					t.Fatalf("token_count rate limits: got %d, want %d", len(agg.TokenCountRateLimits), tc.wantRateLimits)
628				}
629				if hasFinalWarning(warnings, harnesses.UsageWarningMalformed) != tc.wantMalformed {
630					t.Fatalf("malformed warnings: got %#v", warnings)
631				}
632				if hasFinalWarning(warnings, harnesses.UsageWarningDisagreement) != tc.wantDisagreement {
633					t.Fatalf("disagreement warnings: got %#v", warnings)
634				}
635				for _, warning := range warnings {
636					if strings.Contains(warning.Message, "secret prompt") || strings.Contains(warning.Message, "last_token_usage") {
637						t.Fatalf("warning leaked raw token_count content: %#v", warning)
638					}
639				}
640			})
641		}
642	}
