653	func reviewerVerdictFromFinalText(text string) string {
654		if strings.Contains(text, "APPROVE") {
655			return "APPROVE"
656		}
657		if strings.Contains(text, "BLOCK") {
658			return "BLOCK"
659		}
660		return "BLOCK"
661	}
