98	// ReadOpenCodeModelDiscoveryFromCassette reads model discovery data from a recorded
99	// cassette directory. The cassette must follow ADR-002 schema v1.
100	func ReadOpenCodeModelDiscoveryFromCassette(dir string) (harnesses.ModelDiscoverySnapshot, error) {
101		reader, err := cassette.Open(dir)
102		if err != nil {
103			return harnesses.ModelDiscoverySnapshot{}, err
104		}
105		if rec := reader.Discovery(); rec != nil && len(rec.Models) > 0 {
106			return snapshotFromDiscoveryRecord(*rec), nil
107		}
108		text := reader.Final().FinalText
109		if text == "" {
110			frames := reader.Frames()
111			if len(frames) > 0 {
112				text = strings.Join(frames[len(frames)-1].Text, "\n")
113			}
114		}
115		snapshot := opencodeDiscoveryFromText(text, "cassette")
116		if len(snapshot.Models) == 0 {
117			return harnesses.ModelDiscoverySnapshot{}, fmt.Errorf("no models found in opencode model cassette")
118		}
119		return snapshot, nil
120	}
