122	func opencodeDiscoveryFromText(text, source string) harnesses.ModelDiscoverySnapshot {
123		snapshot := harnesses.ModelDiscoverySnapshot{
124			CapturedAt:      time.Now().UTC(),
125			ReasoningLevels: []string{"minimal", "low", "medium", "high", "max"},
126			FreshnessWindow: openCodeModelDiscoveryFreshnessWindow.String(),
127		}
128		if source != "" {
129			snapshot.Source = source
130		}
131		if evidence, err := parseOpenCodeVerboseModelEvidence(text); err == nil && len(evidence) > 0 {
132			snapshot.Models = modelsFromOpenCodeEvidence(evidence)
133			if levels := reasoningLevelsFromOpenCodeEvidence(evidence); len(levels) > 0 {
134				snapshot.ReasoningLevels = levels
135			}
136			snapshot.Detail = fmt.Sprintf("opencode models --verbose returned %d model records; per-model costs are present for %d records; opencode run --help documents -m/--model and --variant", len(evidence), countOpenCodeCostEvidence(evidence))
137			return snapshot
138		}
139		if models := parseOpenCodeModels(text); len(models) > 0 {
140			snapshot.Models = models
141		}
142		return snapshot
143	}
