145	func parseOpenCodeModels(text string) []string {
146		text = strings.ReplaceAll(text, "\r\n", "\n")
147		out := make([]string, 0)
148		for _, line := range strings.Split(text, "\n") {
149			line = strings.TrimSpace(line)
150			if line == "" {
151				continue
152			}
153			fields := strings.Fields(line)
154			if len(fields) != 1 {
155				continue
156			}
157			model := fields[0]
158			if !opencodeModelLinePattern.MatchString(model) {
159				continue
160			}
161			out = appendUniqueString(out, model)
162		}
163		return out
164	}
165	
166	func appendUniqueString(values []string, value string) []string {
167		value = strings.TrimSpace(value)
168		if value == "" {
169			return values
170		}
171		for _, existing := range values {
172			if existing == value {
173				return values
174			}
175		}
176		return append(values, value)
177	}
