190	func parseOpenCodeVerboseModelEvidence(text string) ([]openCodeModelEvidence, error) {
191		text = strings.ReplaceAll(text, "\r\n", "\n")
192		lines := strings.Split(text, "\n")
193		records := make([]openCodeModelEvidence, 0)
194		for i := 0; i < len(lines); i++ {
195			model := strings.TrimSpace(lines[i])
196			if !opencodeModelLinePattern.MatchString(model) {
197				continue
198			}
199			j := i + 1
200			for j < len(lines) && strings.TrimSpace(lines[j]) == "" {
201				j++
202			}
203			if j >= len(lines) || !strings.HasPrefix(strings.TrimSpace(lines[j]), "{") {
204				continue
205			}
206			block, next, err := collectOpenCodeJSONBlock(lines, j)
207			if err != nil {
208				return nil, fmt.Errorf("parse verbose model %q: %w", model, err)
209			}
210			record, err := decodeOpenCodeModelEvidence(model, block)
211			if err != nil {
212				return nil, fmt.Errorf("parse verbose model %q: %w", model, err)
213			}
214			records = append(records, record)
215			i = next
216		}
217		if len(records) == 0 {
218			return nil, fmt.Errorf("opencode verbose model output contained no JSON model records")
219		}
220		return records, nil
221	}
222	
223	func collectOpenCodeJSONBlock(lines []string, start int) (string, int, error) {
224		var block strings.Builder
225		depth := 0
226		started := false
227		inString := false
228		escaped := false
229		for i := start; i < len(lines); i++ {
230			if block.Len() > 0 {
231				block.WriteByte('\n')
232			}
233			line := lines[i]
234			block.WriteString(line)
235			for _, r := range line {
236				if escaped {
237					escaped = false
238					continue
239				}
240				if inString {
241					switch r {
242					case '\\':
243						escaped = true
244					case '"':
245						inString = false
246					}
247					continue
248				}
249				switch r {
250				case '"':
251					inString = true
252				case '{':
253					started = true
254					depth++
255				case '}':
256					depth--
257					if depth < 0 {
258						return "", i, fmt.Errorf("unexpected closing brace")
259					}
260				}
261			}
262			if started && depth == 0 {
263				return block.String(), i, nil
264			}
265		}
266		return "", len(lines) - 1, fmt.Errorf("unterminated JSON object")
267	}
