269	func decodeOpenCodeModelEvidence(model, raw string) (openCodeModelEvidence, error) {
270		var env struct {
271			ID         string          `json:"id"`
272			ProviderID string          `json:"providerID"`
273			Status     string          `json:"status"`
274			Cost       json.RawMessage `json:"cost"`
275			Limit      struct {
276				Context int `json:"context"`
277				Output  int `json:"output"`
278			} `json:"limit"`
279			Capabilities struct {
280				Reasoning  bool `json:"reasoning"`
281				ToolCall   bool `json:"toolcall"`
282				Attachment bool `json:"attachment"`
283			} `json:"capabilities"`
284			Variants map[string]json.RawMessage `json:"variants"`
285		}
286		if err := json.Unmarshal([]byte(raw), &env); err != nil {
287			return openCodeModelEvidence{}, err
288		}
289		evidence := openCodeModelEvidence{
290			Model:        model,
291			ProviderID:   env.ProviderID,
292			ModelID:      env.ID,
293			Status:       env.Status,
294			ContextLimit: env.Limit.Context,
295			OutputLimit:  env.Limit.Output,
296			Reasoning:    env.Capabilities.Reasoning,
297			ToolCall:     env.Capabilities.ToolCall,
298			Attachment:   env.Capabilities.Attachment,
299			Variants:     sortedOpenCodeVariantNames(env.Variants),
300		}
301		if len(env.Cost) > 0 && string(env.Cost) != "null" {
302			var cost struct {
303				Input  float64 `json:"input"`
304				Output float64 `json:"output"`
305				Cache  struct {
306					Read  float64 `json:"read"`
307					Write float64 `json:"write"`
308				} `json:"cache"`
309			}
310			if err := json.Unmarshal(env.Cost, &cost); err != nil {
311				return openCodeModelEvidence{}, err
312			}
313			evidence.Cost = &openCodeModelCost{
314				InputUSDPerMTok:      cost.Input,
315				OutputUSDPerMTok:     cost.Output,
316				CacheReadUSDPerMTok:  cost.Cache.Read,
317				CacheWriteUSDPerMTok: cost.Cache.Write,
318			}
319		}
320		return evidence, nil
321	}
322	
323	func sortedOpenCodeVariantNames(variants map[string]json.RawMessage) []string {
324		if len(variants) == 0 {
325			return nil
326		}
327		out := make([]string, 0, len(variants))
328		for variant := range variants {
329			out = append(out, variant)
330		}
331		sort.Slice(out, func(i, j int) bool {
332			left := openCodeVariantRank(out[i])
333			right := openCodeVariantRank(out[j])
334			if left == right {
335				return out[i] < out[j]
336			}
337			return left < right
338		})
339		return out
340	}
341	
342	func openCodeVariantRank(variant string) int {
343		switch variant {
344		case "none", "off":
345			return 0
346		case "minimal":
347			return 1
348		case "low":
349			return 2
350		case "medium":
351			return 3
352		case "high":
353			return 4
354		case "xhigh":
355			return 5
356		case "max":
357			return 6
358		default:
359			return 100
360		}
361	}
362	
363	func modelsFromOpenCodeEvidence(evidence []openCodeModelEvidence) []string {
364		out := make([]string, 0, len(evidence))
365		for _, item := range evidence {
366			out = appendUniqueString(out, item.Model)
367		}
368		return out
369	}
370	
371	func reasoningLevelsFromOpenCodeEvidence(evidence []openCodeModelEvidence) []string {
372		seen := map[string]bool{}
373		for _, item := range evidence {
374			for _, variant := range item.Variants {
375				seen[variant] = true
376			}
377		}
378		order := []string{"none", "minimal", "low", "medium", "high", "xhigh", "max"}
379		out := make([]string, 0, len(seen))
380		for _, variant := range order {
381			if seen[variant] {
382				out = append(out, variant)
383				delete(seen, variant)
384			}
385		}
386		extra := make([]string, 0, len(seen))
387		for variant := range seen {
388			extra = append(extra, variant)
389		}
390		sort.Strings(extra)
391		return append(out, extra...)
392	}
393	
394	func countOpenCodeCostEvidence(evidence []openCodeModelEvidence) int {
395		count := 0
396		for _, item := range evidence {
397			if item.Cost != nil {
398				count++
399			}
400		}
401		return count
402	}
