405	func discoveryRecord(snapshot harnesses.ModelDiscoverySnapshot) cassette.DiscoveryRecord {
406		return cassette.DiscoveryRecord{
407			Source:            snapshot.Source,
408			Status:            "ok",
409			Models:            append([]string(nil), snapshot.Models...),
410			ReasoningLevels:   append([]string(nil), snapshot.ReasoningLevels...),
411			CapturedAt:        snapshot.CapturedAt.UTC().Format(time.RFC3339),
412			FreshnessWindow:   snapshot.FreshnessWindow,
413			StalenessBehavior: "stale model discovery evidence requires authenticated CLI refresh before capability promotion",
414			Metadata:          map[string]any{"detail": snapshot.Detail},
415		}
416	}
